-- GenDB engine variant Q19-conjunct_permutation: template q19.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue
FROM lineitem, part
WHERE
  (
    l_shipinstruct = 'DELIVER IN PERSON'
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND p_size BETWEEN 1 AND 5
    AND l_quantity <= $2 + 10
    AND l_quantity >= $2
    AND p_container IN ('SM CASE', 'SM BOX', 'SM PACK', 'SM PKG')
    AND p_brand = $1
    AND p_partkey = l_partkey
  )
  OR (
    l_shipinstruct = 'DELIVER IN PERSON'
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND p_size BETWEEN 1 AND 10
    AND l_quantity <= $4 + 10
    AND l_quantity >= $4
    AND p_container IN ('MED BAG', 'MED BOX', 'MED PKG', 'MED PACK')
    AND p_brand = $3
    AND p_partkey = l_partkey
  )
  OR (
    l_shipinstruct = 'DELIVER IN PERSON'
    AND l_shipmode IN ('AIR', 'AIR REG')
    AND p_size BETWEEN 1 AND 15
    AND l_quantity <= $6 + 10
    AND l_quantity >= $6
    AND p_container IN ('LG CASE', 'LG BOX', 'LG PACK', 'LG PKG')
    AND p_brand = $5
    AND p_partkey = l_partkey
  )
